  "codebook": {
    "definition": "Credit-claiming occurs when a senator explicitly or implicitly takes personal responsibility for a specific action, achievement, or policy outcome, often highlighting their direct role in securing funding, passing legislation, or advocating for a cause.",
    "clarification": "Credit-claiming is identified when the senator uses first-person language (e.g., 'I secured,' 'I authored,' 'I fought for') or when the text explicitly attributes an action or outcome to the senator's efforts. It includes instances where the senator highlights their advocacy, legislative work, or direct involvement in achieving a result that benefits their constituents or a broader cause.",
    "positive_examples": [
      {
        "document_id": "89",
        "explanation": "Senator Dorgan explicitly states, 'I authored legislation, which was signed into law, that created the National Center designation,' directly taking credit for the legislative achievement."
      },
      {
        "document_id": "2318",
        "explanation": "Senator Durbin states, 'I helped secure an expedited environmental review from the federal government and facilitated the return of the project to the national priority list,' taking direct credit for his role in advancing the South Suburban Airport project."
      },
      {
        "document_id": "3482",
        "explanation": "Senator Mikulski is described as being 'on the Homeland Security Appropriations Subcommittee that funds the AFGP and fights each year to increase its federal funding,' and her statement, 'I will continue to fight to provide the federal support they need,' highlights her personal advocacy and credit-claiming for securing funds for firefighters."
      }
    ],
    "negative_clarification": "Credit-claiming does NOT occur when the senator merely discusses, criticizes, or comments on policies, actions, or events without explicitly or implicitly taking personal responsibility for them. It also does not include general statements of support, opposition, or concern that do not attribute outcomes to the senator's direct efforts.",
